删除日历事件
@param event_info table，事件信息， 同{@link #add_event}的 event_info字段，包含：
        @param start_time_mills number, 事件开始时间，单位毫秒
        @param end_time_mills number, 事件结束时间，单位毫秒
        @param title string, 事件标题
        @param description string，事件描述
        @param event_location string, 时间发生地点
@return
--]]
function M.delete_event(event_info, cb)
    if not event_info or next(event_info) == nil then
        E.LOG.warn(TAG, "delete_event failed, event_info invalid")
        cb(false, EC.CALENDAR_ERROR_CODES.CODE_EVENT_PARAM_INVALID, "params or event is nil")
        return
    end

    check_before_calendar_operation(false, function(succ, ...)
        if succ then
            E.LOG.debug(TAG, "delete_event begin")
            E.Calendar.delete_event(event_info, cb)
        else
            E.LOG.debug(TAG, "delete_event no permission return false")
            if cb then
                cb(false, ...)
            end
        end
    end)
end

--[[
更新日历事件
@param old_event_info table，事件信息。可选，如果不传，则逻辑同add_event
同{@link #add_event}的 event_info字段，包含：
        @param start_time_mills number, 事件开始时间，单位毫秒
