--[[
查询日历事件是否存在，目前只支持精确匹配事件，不支持批量查询事件
@param event_info table，事件信息。必传
event_info字段，包含：
        @param start_time_mills number, 事件开始时间，单位毫秒
        @param end_time_mills number, 事件结束时间，单位毫秒
        @param title string, 事件标题

@return @param exists, true: 存在， false: 不存在
--]]
function M.is_event_exists(event_info, cb)
    M.query_event_id(event_info, function(ret)
        local succ = ret.succ
        if succ then
            local data = ret.data or {}
            local event_id = data.event_id
            local exists = event_id and event_id ~= "" and event_id ~= "0"
            if cb then
                cb(exists)
            end
        else
            if cb then
                cb(false)
            end
        end
    end)
end

return M